import numpy as np
from IQCommon import pandas as pd
from math import ceil
from datetime import date as ddt
from IQData import interface
from IQData.plugins.plugin_history_data_source.data_source_func import dsf_get_trading_dates_storage, dsf_get_exrights
from IQData.plugins.plugin_history_data_source.history_bar_storage import HistoryBarStorage
from IQData.enumerate import AssetType, BarDataEnum, DATA_INDEX, DATA_INDEX_STR, Frequency, VALID_HISTORY_FIELDS
from IQData.fly_enum import CAL_EXRIGHTS_COLUMNS, IS_OPEN, fq_enum
from IQData.utils.datetime_func import convert_int_to_date, convert_int_to_datetime, convert_int14_to_string, change_dtlist_2_intlist, change_2str_of_time_2_datetime
from IQData.utils.common_func import change_df_2_tuplelist, change_symbol_suffix, chang_df_to_round2, get_date_of_range_to_kwargs, set_params_to_kwargs
from IQData.utils.calexrights_func import change_his_to_forward, change_his_to_backward, change_his_to_dynamic_forward
from IQCommon.exception import get_traceback_message
from IQCommon.logger import system_log
class HistoryDataSource(interface.AbstractHistoryQuoteData):
    __doc__ = '\n    基础数据源类,继承自AbstractHistoryQuoteData类,用来提供数据\n    '
    _inited = False
    _HistoryDataSource__last_instance = (None, None)
    def __new__(cls):
        data_path = 'HistoryDataSource'
        (last_path, instance) = cls._HistoryDataSource__last_instance
        if (data_path != last_path):
            instance = super(HistoryDataSource, cls).__new__(cls)
            cls._HistoryDataSource__last_instance = (data_path, instance)
        return instance
    def __init__(self):
        if self._inited:
            return None
        else:
            barslist = []
            for index in DATA_INDEX_STR:
                barslist.append('HistoryBarStorage(%s)' % index)
            else:
                self._bars = barslist
                self._all_trading_dates_of_series = self._get_all_trading_dates_of_series()
                self._inited = True
    def _get_trading_calendar(self):
        return dsf_get_trading_dates_storage().get_trading_calendar()
    def _get_all_trading_dates_of_series(self):
        _all_trading_dates = self._get_trading_calendar()
        _all_trading_dates_of_series = pd.Series(np.arange(len(_all_trading_dates)), index=_all_trading_dates)
        return _all_trading_dates_of_series
    def _get_pre_date(self, bar_count, cur_date, frequency):
        pre_date_count = 1
        if (frequency.find(Frequency.DAILY.value) > -1):
            pre_date_count = bar_count
        elif (frequency.find(Frequency.MINUTE.value) > -1):
            pre_date_count = ceil(bar_count / 240)
        elif (frequency.find(Frequency.TICK.value) > -1):
            pre_date_count = ceil(bar_count / 4800)
        elif (frequency.find(Frequency.MINUTE5.value) > -1):
            pre_date_count = ceil(bar_count / 48.0)
        elif (frequency.find(Frequency.MINUTE15.value) > -1):
            pre_date_count = ceil(bar_count / 16.0)
        elif (frequency.find(Frequency.MINUTE30.value) > -1):
            pre_date_count = ceil(bar_count / 8.0)
        elif (frequency.find(Frequency.MINUTE60.value) > -1):
            pre_date_count = ceil(bar_count / 4.0)
        if (pre_date_count > 0):
            pre_data = self._all_trading_dates_of_series.ix[:cur_date].ix[pre_date_count * -1 - 1:].ix[:1]
        else:
            pre_data = self._all_trading_dates_of_series.ix[cur_date:].ix[:pre_date_count * -1 + 1].ix[-1:]
        return pre_data.index[0]
    def _get_current_bar_storage(self, assettype, frequency):
        index = DATA_INDEX.index((assettype, frequency))
        try:
            bar_storage = self._bars[index]
            if isinstance(bar_storage, str):
                self._bars[index] = eval(bar_storage)
        except:
            system_log.error(get_traceback_message())
            bar_storage = HistoryBarStorage((assettype, frequency))
            self._bars[index] = bar_storage
        finally:
            self._bars[index]
            return None
    def _all_bars_of_range(self, asset, start_time, end_time, frequency):
        bar_storage = self._get_current_bar_storage(asset.type, frequency)
        data_dataframe = bar_storage.get_bar(asset.symbol, start_time, end_time)
        if (len(data_dataframe) > 0):
            return data_dataframe
        else:
            return pd.DataFrame()
    def get_bars(self, asset, start_time, end_time, frequency, fields=None):
        param = set_params_to_kwargs(asset, start_time, end_time, frequency)
        bars = self._all_bars_of_range(**param)
        (source_start, source_end) = change_2str_of_time_2_datetime(start_time, end_time)
        if (len(bars) > 0):
            if (fields is not None):
                bar = bars.ix[source_start:source_end, fields]
            else:
                bar = bars.ix[source_start:source_end, :]
            if (len(bar) > 0):
                return change_df_2_tuplelist(bar, frequency)
            return None
    def get_bar(self, asset, dt, frequency, fields=None):
        param = get_date_of_range_to_kwargs(asset, dt, frequency)
        bars = self._all_bars_of_range(**param)
        if (dt not in bars.index):
            return None
        elif (len(bars) > 0):
            if (fields is not None):
                tmpdf = bars.ix[:dt]
                bar = tmpdf.ix[-1:, fields]
            else:
                tmpdf = bars.ix[:dt]
                bar = tmpdf.ix[-1:]
            if (len(bar) > 0):
                return change_df_2_tuplelist(bar.copy(), frequency)[0]
            return None
        else:
            return None
    def _change_his_to_data(self, symbol, data, cur_date, fq=None, tmpindex=None):
        if (data is None or data.empty):
            return data
        elif (fq == fq_enum[2]):
            exrights_data = self.get_exrights_info(symbol)
            return change_his_to_dynamic_forward(symbol, data, exrights_data, cur_date, fq, tmpindex)
        else:
            if (fq == fq_enum[0]):
                exrights_data = self.get_exrights_info(symbol)
                return change_his_to_forward(symbol, data, exrights_data, fq)
            elif (fq == fq_enum[1]):
                exrights_data = self.get_exrights_info(symbol)
                return change_his_to_backward(symbol, data, exrights_data, fq)
            return data
    def get_price(self, asset, start_date, end_date, frequency=Frequency.DAILY.value, fields=None, fq=None, skip_suspended=False):
        if isinstance(start_date, int):
            start_date = convert_int14_to_string(start_date)
        if isinstance(end_date, int):
            end_date = convert_int14_to_string(end_date)
        if (fields is None):
            fields = VALID_HISTORY_FIELDS.copy()
        if (not isinstance(fields, list)):
            fields = [fields]
        bar_storage = self._get_current_bar_storage(asset.type, frequency)
        symbol = asset.symbol
        symbol = change_symbol_suffix(symbol)
        data_dataframe = bar_storage.get_price_bar(symbol, start_date, end_date, frequency, fields, fq, skip_suspended)
        data_dataframe[BarDataEnum.DATETIME.value] = change_dtlist_2_intlist(data_dataframe.index, frequency)
        data_dataframe = data_dataframe.reset_index(drop=True)
        data_dataframe = chang_df_to_round2(data_dataframe)
        return data_dataframe.ix[:, fields]
    def get_kline_by_count(self, asset, count, query_date, frequency, fields=None, fq=None, skip_suspended=False, include=False):
        cur_date = convert_int_to_date(query_date)
        pre_date = self._get_pre_date(count, cur_date, frequency)
        if (count > 0):
            params = set_params_to_kwargs(asset, pre_date, cur_date, frequency)
        else:
            params = set_params_to_kwargs(asset, cur_date, pre_date, frequency)
        if (fields is None):
            fields = VALID_HISTORY_FIELDS.copy()
        tmp_field = []
        tmp_field_index_list = []
        if isinstance(fields, list):
            tmp_field = fields.copy()
        else:
            fields = [fields]
            tmp_field = fields.copy()
        if (fq == fq_enum[2]):
            tmp_field_index_list = [tmp_field.index(field) for field in tmp_field if field in CAL_EXRIGHTS_COLUMNS]
        if (IS_OPEN not in tmp_field):
            tmp_field.append(IS_OPEN)
        data_dataframe = self._all_bars_of_range(**params)
        if (frequency[-1] == Frequency.MINUTE.value[-1]):
            cur_date = convert_int_to_datetime(query_date)
        if (count > 0):
            data_dataframe = data_dataframe.ix[:cur_date]
            if (include or cur_date not in data_dataframe.index):
                data_dataframe = data_dataframe.ix[count * -1:, tmp_field]
            else:
                data_dataframe = data_dataframe.ix[count * -1 - 1:-1, tmp_field]
        else:
            data_dataframe = data_dataframe.ix[cur_date:]
            if include:
                data_dataframe = data_dataframe.ix[:count * -1, tmp_field]
            else:
                data_dataframe = data_dataframe.ix[1:count * -1 + 1, tmp_field]
        data_dataframe = self._change_his_to_data(asset.symbol, data_dataframe, cur_date, fq, tmp_field_index_list)
        data_dataframe[BarDataEnum.DATETIME.value] = change_dtlist_2_intlist(data_dataframe.index, frequency)
        data_dataframe = data_dataframe.reset_index(drop=True)
        data_dataframe = chang_df_to_round2(data_dataframe)
        return data_dataframe.ix[:, fields]
    def get_kline_by_date(self, asset, start_date, end_date, frequency, fields=None, fq=None, skip_suspended=False, include=False):
        params = set_params_to_kwargs(asset, start_date, end_date, frequency)
        if (fields is None):
            fields = VALID_HISTORY_FIELDS.copy()
        tmp_field = []
        tmp_field_index_list = []
        if isinstance(fields, list):
            tmp_field = fields.copy()
        else:
            fields = [fields]
            tmp_field = fields.copy()
        if (fq == fq_enum[2]):
            tmp_field_index_list = [tmp_field.index(field) for field in tmp_field if field in CAL_EXRIGHTS_COLUMNS]
        if (IS_OPEN not in tmp_field):
            tmp_field.append(IS_OPEN)
        data_dataframe = self._all_bars_of_range(**params)
        if (frequency[-1] == Frequency.MINUTE.value[-1]):
            pre_date = convert_int_to_datetime(start_date)
            cur_date = convert_int_to_datetime(end_date)
        else:
            pre_date = convert_int_to_date(start_date)
            cur_date = convert_int_to_date(end_date)
        if (len(data_dataframe) > 0):
            data_dataframe = data_dataframe.ix[pre_date:cur_date]
        data_dataframe = self._change_his_to_data(asset.symbol, data_dataframe, cur_date, fq, tmp_field_index_list)
        data_dataframe[BarDataEnum.DATETIME.value] = change_dtlist_2_intlist(data_dataframe.index, frequency)
        data_dataframe = data_dataframe.reset_index(drop=True)
        data_dataframe = chang_df_to_round2(data_dataframe)
        return data_dataframe.ix[:, fields]
    def get_settle_price(self, symbol, dt):
        data = self.get_bar(symbol, dt, Frequency.DAILY.value, ['close'])
        if (data is None):
            redata = np.nan
        else:
            redata = round(data[1], 2)
        return redata
    def get_prev_settlement(self, symbol, dt):
        all_trading_dates = self._get_trading_calendar()
        if (dt in all_trading_dates):
            pre_dt = self._all_trading_dates_of_series.ix[:dt].ix[-2:-1].index[0]
        else:
            pre_dt = self._all_trading_dates_of_series.ix[:dt].ix[-1:].index[0]
        return self.get_settle_price(symbol, pre_dt)
    return (__classcell__ := __class__)
